rest.assertionCode:
def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 400 or not isinstance(responseBody, dict):
        return False
    code = responseBody.get("code")
    if not (isinstance(code, int) and not isinstance(code, bool)) or code != 40001:
        return False
    if not all(key in responseBody for key in ("code", "message", "data", "requestId")):
        return False
    assert set(responseBody.keys()) <= {"code", "message", "data", "requestId"}
    request_id = responseBody.get("requestId")
    message = responseBody.get("message")
    if not isinstance(request_id, str) or not request_id.strip():
        return False
    if not isinstance(message, str) or not message.strip():
        return False
    details = (message + " " + str(responseBody.get("data"))).lower()
    for leak in ("exception", "traceback", "\tat ", "at com.", "at java.", "at org.", "at sun."):
        assert leak not in details, "响应暴露了堆栈或异常类型"
    return True
